#include <zephyr/kernel.h>
#include <zephyr/device.h> 
#include <zephyr/init.h>
#include <zephyr/ztest.h>
#include <zephyr/pm/device.h>

#include "test_device.h"
#include "test_device_api.h"
#include "test_driver_init.h"

#define DUMMY_DEVICE_NODE DT_NODELABEL(dummy_device)

static int test_device_init(const struct device *d)
{
	const struct test_device_config *cfg = d->config;

	*(cfg->state) = 1;

	return 0;
}

static int test_device_init_fail(const struct device *d)
{
	const struct test_device_config *cfg = d->config;

	*(cfg->state) = 1;

	return -1;
}

static int test_device_deinit(const struct device *d)
{
	const struct test_device_config *cfg = d->config;

	*(cfg->state) = 0;

	return 0;
}

static int test_device_pm_action(const struct device *d,
				 enum pm_device_action action)
{
	ARG_UNUSED(d);
	ARG_UNUSED(action);

	return 0;
}

#define TEST_DEVICE_DEFINE(name, level, prio, init, deinit, pm) \
	static int test_device_state_##name; \
	static const struct test_device_config test_device_config_##name = { \
		.state = &test_device_state_##name, \
	}; \
	PM_DEVICE_DT_DEFINE(DUMMY_DEVICE_NODE, test_device_pm_action); \
	DEVICE_DEFINE(name, "test_device", init, deinit, \
		      NULL, &test_device_config_##name, \
		      level, prio, &test_device_apis)

TEST_DEVICE_DEFINE(test_device, POST_KERNEL, 0,
		   test_device_init, test_device_deinit,
		   PM_DEVICE_DT_GET(DUMMY_DEVICE_NODE));
TEST_DEVICE_DEFINE(test_device_fail, POST_KERNEL, 0,
		   test_device_init_fail, NULL,
		   PM_DEVICE_DT_GET(DUMMY_DEVICE_NODE));

static void test_device_get_binding_success(void)
{
	const struct device *dev;

	dev = device_get_binding("test_device");
	zassert_not_null(dev, "device_get_binding() has failed");

	dev = DEVICE_GET(test_device);
	zassert_not_null(dev, "DEVICE_GET() has failed");
}

static void test_device_get_binding_failure(void)
{
	const struct device *dev;

	dev = device_get_binding("test_device_not_exists");
	zassert_is_null(dev, "device_get_binding() has failed");
}

static void test_device_ready_success(void)
{
	const struct device *dev = DEVICE_GET(test_device);
	bool is_ready;

	is_ready = device_is_ready(dev);
	zassert_true(is_ready, "device_is_ready() has failed");
}

static void test_device_ready_failure(void)
{
	const struct device *dev = DEVICE_GET(test_device_fail);
	bool is_ready;

	is_ready = device_is_ready(dev);
	zassert_false(is_ready, "device_is_ready() has failed");
}

/*
 * Used to verify the device initialization ordering.
 * The initialization priority is stored in the device config.
 */

static const void *init_record[15];
static int init_record_idx;

static int dummy_init(const struct device *d)
{
	init_record[init_record_idx++] = d;
	return 0;
}

#define DUMMY_DEVICE_DEFINE(level, prio, _name) \
	static int _name##_prio = prio; \
	DEVICE_DEFINE(_name, "", dummy_init, NULL, NULL, \
		      &_name##_prio, level, prio, NULL)

/* PRE_KERNEL_1 */
DUMMY_DEVICE_DEFINE(PRE_KERNEL_1, 11, dev_pre_1_11);
DUMMY_DEVICE_DEFINE(PRE_KERNEL_1, 10, dev_pre_1_10);

/* PRE_KERNEL_2 */
DUMMY_DEVICE_DEFINE(PRE_KERNEL_2, 21, dev_pre_2_21);
DUMMY_DEVICE_DEFINE(PRE_KERNEL_2, 20, dev_pre_2_20);

/* POST_KERNEL */
DUMMY_DEVICE_DEFINE(POST_KERNEL, 31, dev_post_31);
DUMMY_DEVICE_DEFINE(POST_KERNEL, 30, dev_post_30);

/* APPLICATION */
DUMMY_DEVICE_DEFINE(APPLICATION, 41, dev_app_41);
DUMMY_DEVICE_DEFINE(APPLICATION, 40, dev_app_40);

/* Also test regular SYS_INIT calls to make sure they are properly ordered */
static int sys_init_pre1(const struct device *d)
{
	ARG_UNUSED(d);
	init_record[init_record_idx++] = sys_init_pre1;
	return 0;
}

SYS_INIT(sys_init_pre1, SYS_INIT_LEVEL_PRE_KERNEL_1, 12);

static int sys_init_post(const struct device *d)
{
	ARG_UNUSED(d);
	init_record[init_record_idx++] = sys_init_post;
	return 0;
}

SYS_INIT(sys_init_post, SYS_INIT_LEVEL_POST_KERNEL, 32);

static int sys_init_app(const struct device *d)
{
	ARG_UNUSED(d);
	init_record[init_record_idx++] = sys_init_app;
	return 0;
}

SYS_INIT(sys_init_app, SYS_INIT_LEVEL_APPLICATION, 42);

static void test_device_init_level(void)
{
	const void *expected_seq[] = {
		&__device_dev_pre_1_10,
		&__device_dev_pre_1_11,
		sys_init_pre1,
		&__device_dev_pre_2_20,
		&__device_dev_pre_2_21,
		&__device_dev_post_30,
		&__device_dev_post_31,
		sys_init_post,
		&__device_dev_app_40,
		&__device_dev_app_41,
		sys_init_app,
	};
	bool seq_correct = true;
	int i;

	zassert_equal(init_record_idx, ARRAY_SIZE(expected_seq),
		      "Incorrect number of initializations");

	TC_PRINT("Checking order of %d initializations\n", init_record_idx);

	for (i = 0; i < init_record_idx; i++) {
		if (init_record[i] != expected_seq[i]) {
			/* This is tricky because we can't print device names */
			TC_PRINT("Init %d: expected %p, got %p\n",
				 i, expected_seq[i], init_record[i]);
			seq_correct = false;
		}
	}

	zassert_true(seq_correct, "Device init sequence wrong");
}

static void test_device_api(void)
{
	const struct device *dev = DEVICE_GET(test_device);
	const struct test_device_api *api = dev->api;

	zassert_not_null(api, "API is null");
	zassert_not_null(api->f1, "API f1 is null");
	zassert_not_null(api->f2, "API f2 is null");
	zassert_is_null(api->f3, "API f3 is not null");

	api->f1(dev);
	api->f2(dev);
}

static void test_device_api_extends(void)
{
	const struct device *dev = DEVICE_GET(test_device_sub);
	const struct test_sub_device_api *api = dev->api;

	zassert_not_null(api, "API is null");
	zassert_not_null(api->f1, "API f1 is null");
	zassert_not_null(api->f2, "API f2 is null");
	zassert_not_null(api->f3, "API f3 is null");

	api->f1(dev);
	api->f2(dev);
	api->f3(dev);
}

static void test_device_api_extends_sibling(void)
{
	const struct device *dev = DEVICE_GET(test_device_sub_sibling);
	const struct test_sub_device_api *api = dev->api;

	zassert_not_null(api, "API is null");
	zassert_not_null(api->f1, "API f1 is null");
	zassert_not_null(api->f2, "API f2 is null");
	zassert_not_null(api->f3, "API f3 is null");

	api->f1(dev);
	api->f2(dev);
	api->f3(dev);
}

static void test_device_api_extends_grandchild(void)
{
	const struct device *dev = DEVICE_GET(test_device_sub_grandchild);
	const struct test_grandchild_device_api *api = dev->api;

	zassert_not_null(api, "API is null");
	zassert_not_null(api->f1, "API f1 is null");
	zassert_not_null(api->f2, "API f2 is null");
	zassert_not_null(api->f3, "API f3 is null");
	zassert_not_null(api->f4, "API f4 is null");

	api->f1(dev);
	api->f2(dev);
	api->f3(dev);
	api->f4(dev);
}

static void test_deinit_not_supported(void)
{
	const struct device *dev = DEVICE_GET(test_device_fail);
	int err;

	err = device_deinit(dev);
	zassert_equal(err, -ENOSYS, "device_deinit() has failed");
}

static void test_deinit_success_and_redeinit(void)
{
	const struct device *dev = DEVICE_GET(test_device);
	const struct test_device_config *cfg = dev->config;
	int err;

	zassert_equal(*cfg->state, 1, "Device not initialized");

	err = device_deinit(dev);
	zassert_equal(err, 0, "device_deinit() has failed");
	zassert_equal(*cfg->state, 0, "Device not deinitialized");

	err = device_init(dev);
	zassert_equal(err, 0, "device_init() has failed");
	zassert_equal(*cfg->state, 1, "Device not reinitialized");
}

void test_main(void)
{
	ztest_test_suite(device,
			 ztest_unit_test(test_device_get_binding_success),
			 ztest_unit_test(test_device_get_binding_failure),
			 ztest_unit_test(test_device_ready_success),
			 ztest_unit_test(test_device_ready_failure),
			 ztest_unit_test(test_deinit_not_supported),
			 ztest_unit_test(test_deinit_success_and_redeinit),
			 ztest_unit_test(test_device_api),
			 ztest_unit_test(test_device_api_extends),
			 ztest_unit_test(test_device_api_extends_sibling),
			 ztest_unit_test(test_device_api_extends_grandchild),
			 ztest_unit_test(test_device_init_level)
			 );
	ztest_run_test_suite(device);
}
